CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE IF NOT EXISTS services(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name text NOT NULL,description text NOT NULL DEFAULT '',duration_minutes int NOT NULL CHECK(duration_minutes>0),price_ars int NOT NULL CHECK(price_ars>=0),active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS business_hours(day_of_week int PRIMARY KEY CHECK(day_of_week BETWEEN 0 AND 6),open_time time NOT NULL,close_time time NOT NULL,enabled boolean NOT NULL DEFAULT true,CHECK(close_time>open_time));
CREATE TABLE IF NOT EXISTS blocked_periods(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,reason text NOT NULL DEFAULT '',CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS patients(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,full_name text NOT NULL,phone text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS appointments(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,service_id bigint NOT NULL REFERENCES services(id),patient_id bigint NOT NULL REFERENCES patients(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,blocked_until timestamptz NOT NULL,status text NOT NULL DEFAULT 'confirmed' CHECK(status IN ('confirmed','completed','cancelled','no_show')),payment_status text NOT NULL DEFAULT 'pending' CHECK(payment_status IN ('pending','paid')),price_ars int NOT NULL CHECK(price_ars>=0),created_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at AND blocked_until>=ends_at),CONSTRAINT appointments_no_overlap EXCLUDE USING gist(tstzrange(starts_at,blocked_until,'[)') WITH &&) WHERE(status IN ('confirmed','completed','no_show')));
INSERT INTO services(name,description,duration_minutes,price_ars) SELECT * FROM (VALUES('Sesión Premium','Descontracturante profundo + relajante corporal + sedativo cráneo-facial (incluye rostro)',90,30000),('Alivio Localizado','Focalizado en zonas de tensión: espalda, cuello y hombros',50,20000),('Masaje Express','Rápido y efectivo, ideal para una pausa laboral',30,15000)) AS v(name,description,duration_minutes,price_ars) WHERE NOT EXISTS(SELECT 1 FROM services);
