INSERT INTO business_hours(day_of_week,open_time,close_time,enabled) VALUES(1,'09:00','19:00',true),(2,'09:00','19:00',true),(3,'09:00','19:00',true),(4,'09:00','19:00',true),(5,'09:00','19:00',true),(6,'09:00','13:00',true),(0,'09:00','13:00',false) ON CONFLICT(day_of_week) DO NOTHING;
